"use client"
import React from "react";
import StatButton from "./StatButton";
import FieldEntry from "./FieldEntry";
import { useEffect, useState } from "react";

function StatButtonContainer({ label, endpoint, loading, submit } : {label : string, endpoint: string, loading: number, submit : (stat: string, value: string, selected : boolean) => void}){

    const [stats, setStats] = useState<string[]>([]);

    function handleSelect(stat: string, value: string, selected: boolean){
        submit(stat, value, selected);
    }

    useEffect(() => {

        async function loadHome() {
            loading = 0;
            try {
                const res = await fetch(`http://localhost:5000${endpoint}`)
                const data = await res.json()
                setStats(data);
                console.log(data)
            } catch (e) {
                console.log(`Error fetching at home ${e}`)
            }
        }
        loading = 1;
        loadHome();
    }, []);


    return(
        <div className={loading === 1 
        ? `flex items-center justify-center flex-col gap-2` 
        : loading=== 0 
            ? "flex items-center justify-center flex-col gap-2 animate-pulse"
            : "hidden"}>
            <h1 className="font-bold text-xl">{label}</h1>
            <div className="flex flex-row gap-4 flex-wrap items-center justify-center w-4/5 py-4 px-4 bg-[#051122] rounded-sm">
                {stats.map((stat, index) => (
                    <StatButton 
                    key={index} 
                    label={stat} 
                    onSelect={handleSelect}>
                    </StatButton>
                ))}
            </div>
            <div className="flex flex-row gap-4 flex-wrap items-center justify-center w-4/5 py-4 px-4 bg-[#051122] rounded-sm">
                {stats.map((stat, index) => (
                    <StatButton 
                    key={index} 
                    label={stat} 
                    onSelect={handleSelect}>
                    </StatButton>
                ))}
            </div>
        </div>

    )
}

export default StatButtonContainer;