"use client"

import StatButtonContainer from "./components/StatButtonContainer";
import Btn from "./components/btn";
import Loader from "./components/loader";
import { useState, useEffect } from "react";
import { StatEntry } from "./types/stats";

export default function Home() {

  const [mainContentState, setMainContentState] = useState(1)
  const selectedStats : Record<string, StatEntry> = {}

  async function submit(){
    setMainContentState(2);
    const stats = selectedStats;
    try {
      const response = await fetch("http://localhost:5000/submit", {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify(stats)
      })

    } catch (error){
      console.log(`Error sending the stats up ${error}`)
    }
  }

  function getStats(stat: string, value: string, selected: boolean){
    if (stat in selectedStats){
      console.log(selectedStats[stat])
      selectedStats[stat] = {"selected" : selected, "value":value}
    } else {
      selectedStats[stat] = {"selected" : true, "value":value};
    }
  }

  return (
    <div className="flex flex-col flex-1 items-center justify-center bg-zinc-50 font-sans dark:bg-[#000a19] gap-4">
      <header className="flex items-center p-2 top-0 left-0 w-full dark:bg-[#4e55e3] text-2xl"><h1>Perfect Team</h1></header>
      <main className="flex flex-col items-center">
        <StatButtonContainer label="League Settings" endpoint="/settings" loading={mainContentState} submit={getStats}></StatButtonContainer>
        <StatButtonContainer label="Offensive Stats" endpoint="/offense" loading={mainContentState} submit={getStats}></StatButtonContainer>
        <StatButtonContainer label="Defensive Stats" endpoint="/defense" loading={mainContentState} submit={getStats}></StatButtonContainer>
      </main>
      <Loader state={mainContentState}></Loader>
      <Btn label="Calculate" action={submit} loading={mainContentState}></Btn>
    </div>
  );
}
